package com.hms.website;
import com.hms.departments.*; import com.hms.doctors.*; import com.hms.services.*; import com.hms.tenancy.*; import java.util.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/public/hospitals/{tenantSlug}") public class PublicDirectoryController {private final TenantRepository tenants;private final DepartmentRepository departments;private final DoctorRepository doctors;private final HospitalServiceRepository services;public PublicDirectoryController(TenantRepository t,DepartmentRepository d,DoctorRepository dr,HospitalServiceRepository s){tenants=t;departments=d;doctors=dr;services=s;} @GetMapping("/departments") public List<DepartmentDto> departments(@PathVariable String tenantSlug){UUID t=tenant(tenantSlug);return departments.findAllByTenantIdOrderByName(t).stream().filter(Department::isActive).map(DepartmentDto::from).toList();} @GetMapping("/doctors") public List<DoctorDto> doctors(@PathVariable String tenantSlug){UUID t=tenant(tenantSlug);return doctors.findAllByTenantIdOrderByDisplayName(t).stream().filter(d->d.isActive()&&d.isPublicVisible()).map(d->new DoctorDto(d.getId(),d.getDisplayName(),d.getSpecialty(),d.getPhotoUrl(),d.getQualifications(),d.getExperienceYears(),d.getLanguages(),d.getConsultationTimings(),d.isPublicVisible(),d.isActive(),Set.of())).toList();} @GetMapping("/services") public List<HospitalService> services(@PathVariable String tenantSlug){UUID t=tenant(tenantSlug);return services.findAllByTenantIdOrderByNameAsc(t).stream().filter(s->s.isActive()&&s.isPublicVisible()).toList();} private UUID tenant(String s){return tenants.findBySlug(s).map(Tenant::getId).orElseThrow(()->new TenantNotFoundException(s));}}
